/*
 * SCIENCE & RESEARCH 09 — ELECTROCHEMICAL RESEARCH CELL
 * Pure Canvas 2D; one scene; seamless 25-second loop.
 * time is in SECONDS. Suggested export: 3840 x 2160 at 60 fps.
 * Export encoder requirement: at least 100,000,000 bits/second.
 * Canvas draws frames; the exporting encoder must enforce bitrate.
 * Ion lanes, porous separator, and external electron circuit are distinct.
 * No assets, dependencies, DOM, 3D, blur, or background glow.
 */
function draw(ctx, time, width, height) {
  const t = time;
  const duration = 25;
  const sceneCount = 1;
  const loopT = ((t % duration) + duration) % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;
  const minSide = Math.min(width, height);
  if (!(minSide > 0) || !Number.isFinite(t)) return;

  const TAU = Math.PI * 2;
  const phase = TAU * (currentScene + sceneProgress);
  const charge = 0.5 - 0.5 * Math.cos(phase);
  const velocity = Math.sin(phase);
  const current = Math.sqrt(velocity * velocity + 0.005) / Math.sqrt(1.005);
  const direction = velocity / Math.sqrt(velocity * velocity + 0.03);
  const unit = Math.min(minSide / 1060, width / 1190);
  const ink = '#102a39';
  const fract = v => v - Math.floor(v);
  const clamp = v => Math.max(0, Math.min(1, v));
  const ease = v => { const q = clamp(v); return q*q*q*(q*(q*6-15)+10); };
  const mix = (a,b,q) => 'rgb('+a.map((v,i)=>Math.round(v+(b[i]-v)*q)).join(',')+')';
  const lanes = [-122,-56,10,76,142];
  function rr(x,y,w,h,r,fill,stroke,weight) {
    r=Math.max(0,Math.min(r,w/2,h/2));
    ctx.beginPath();ctx.moveTo(x+r,y);ctx.lineTo(x+w-r,y);
    ctx.quadraticCurveTo(x+w,y,x+w,y+r);ctx.lineTo(x+w,y+h-r);
    ctx.quadraticCurveTo(x+w,y+h,x+w-r,y+h);ctx.lineTo(x+r,y+h);
    ctx.quadraticCurveTo(x,y+h,x,y+h-r);ctx.lineTo(x,y+r);
    ctx.quadraticCurveTo(x,y,x+r,y);ctx.closePath();
    if(fill){ctx.fillStyle=fill;ctx.fill();}
    if(stroke){ctx.strokeStyle=stroke;ctx.lineWidth=weight||4;ctx.stroke();}
  }
  function line(x1,y1,x2,y2,color,weight) {
    ctx.beginPath();ctx.moveTo(x1,y1);ctx.lineTo(x2,y2);
    ctx.strokeStyle=color;ctx.lineWidth=weight;ctx.stroke();
  }
  function circle(x,y,r,fill,stroke,weight) {
    ctx.beginPath();ctx.arc(x,y,r,0,TAU);
    if(fill){ctx.fillStyle=fill;ctx.fill();}
    if(stroke){ctx.strokeStyle=stroke;ctx.lineWidth=weight||3;ctx.stroke();}
  }
  function wirePath() {
    ctx.beginPath();ctx.moveTo(-240,-279);ctx.lineTo(-240,-338);
    ctx.arc(-214,-338,26,Math.PI,Math.PI*1.5);
    ctx.lineTo(94,-364);ctx.arc(94,-338,26,-Math.PI/2,0);
    ctx.lineTo(120,-279);
  }
  const cornerLength=26*Math.PI/2,wireLength=59+cornerLength+308+cornerLength+59;
  function wirePoint(u) {
    let d=u*wireLength;
    if(d<59)return {x:-240,y:-279-d};d-=59;
    if(d<cornerLength){const a=Math.PI+d/26;return {x:-214+26*Math.cos(a),y:-338+26*Math.sin(a)};}d-=cornerLength;
    if(d<308)return {x:-214+d,y:-364};d-=308;
    if(d<cornerLength){const a=-Math.PI/2+d/26;return {x:94+26*Math.cos(a),y:-338+26*Math.sin(a)};}d-=cornerLength;
    return {x:120,y:-338+d};
  }

  ctx.save();ctx.setTransform(1,0,0,1,0,0);
  ctx.globalAlpha=1;ctx.globalCompositeOperation='source-over';
  ctx.shadowBlur=0;ctx.shadowOffsetX=0;ctx.shadowOffsetY=0;
  ctx.setLineDash([]);ctx.lineCap='round';ctx.lineJoin='round';
  const bg=ctx.createLinearGradient(0,0,width,height);
  bg.addColorStop(0,'#0d1e2d');bg.addColorStop(0.53,'#173b47');bg.addColorStop(1,'#244653');
  ctx.fillStyle=bg;ctx.fillRect(0,0,width,height);
  ctx.translate(width/2-27*unit,height/2+8*unit);ctx.scale(unit,unit);
  ctx.beginPath();ctx.ellipse(32,390,429,11,0,0,TAU);
  ctx.fillStyle='rgba(3,14,25,0.28)';ctx.fill();

  // Rounded external circuit has continuous tangents at both upper corners.
  wirePath();ctx.strokeStyle=ink;ctx.lineWidth=12;ctx.stroke();
  wirePath();ctx.strokeStyle='#86b2c2';ctx.lineWidth=5;ctx.stroke();
  for(let i=0;i<6;i++){
    const u=fract(-3*charge+i/6),p=wirePoint(u);
    ctx.save();ctx.globalAlpha=Math.pow(Math.sin(Math.PI*u),2)*0.90;
    circle(p.x,p.y,4.2,'#bddfd9');ctx.restore();
  }
  rr(219,-128,70,20,6,'#7294a9',ink,4);
  rr(219,141,70,20,6,'#7294a9',ink,4);

  // A single planar cell housing, with stable rigid boundaries.
  const body=ctx.createLinearGradient(-340,-230,220,255);
  body.addColorStop(0,'#6d98a9');body.addColorStop(1,'#4f7b91');
  rr(-340,-230,560,485,28,body,ink,7);
  rr(-322,-211,524,448,17,'#234b5c','#9bbec9',3.5);
  ctx.save();rr(-318,-207,516,440,14);ctx.clip();
  const electrolyte=ctx.createLinearGradient(0,-166,0,237);
  electrolyte.addColorStop(0,'#3e7c88');electrolyte.addColorStop(1,'#2c606f');
  function liquidY(x){return -164+4*Math.sin(phase*2)+2*Math.sin((x+300)/80+phase*4);}
  ctx.beginPath();
  for(let i=0;i<=80;i++){const x=-325+i*530/80;if(i===0)ctx.moveTo(x,liquidY(x));else ctx.lineTo(x,liquidY(x));}
  ctx.lineTo(205,242);ctx.lineTo(-325,242);ctx.closePath();ctx.fillStyle=electrolyte;ctx.fill();
  ctx.beginPath();
  for(let i=0;i<=80;i++){const x=-325+i*530/80;if(i===0)ctx.moveTo(x,liquidY(x));else ctx.lineTo(x,liquidY(x));}
  ctx.strokeStyle='#7fb7b9';ctx.lineWidth=2.2;ctx.stroke();ctx.restore();

  // Electrode stems remain attached to their fixed-polarity terminals.
  rr(-250,-221,20,47,5,'#8bafc1',ink,3.5);
  rr(110,-221,20,47,5,'#bea779',ink,3.5);
  const leftPlate=ctx.createLinearGradient(-279,0,-201,0);
  leftPlate.addColorStop(0,'#73b9c7');leftPlate.addColorStop(1,'#92cbd0');
  rr(-279,-184,78,380,12,leftPlate,ink,5);
  const rightPlate=ctx.createLinearGradient(80,0,158,0);
  rightPlate.addColorStop(0,'#d8b37c');rightPlate.addColorStop(1,'#e5c591');
  rr(80,-184,78,380,12,rightPlate,ink,5);
  for(let i=0;i<8;i++){
    rr(-261,-162+i*43,42,15,5,'#528d9e');
    rr(98,-162+i*43,42,15,5,'#b28c62');
  }
  for(const y of lanes)line(-170,y,49,y,'rgba(145,193,199,0.14)',1.5);

  // Open horizontal pores are cut through the separator's structural outline.
  rr(-66,-222,12,25,4,'#99b8c6',ink,3);
  rr(-75,-194,30,400,8,'#8eafbd',ink,4);
  for(const y of lanes){
    ctx.fillStyle='#326977';ctx.fillRect(-78,y-14,36,28);
    line(-74,y-14,-46,y-14,'#b4ccd1',2.3);
    line(-74,y+14,-46,y+14,'#b4ccd1',2.3);
  }
  rr(-86,-209,52,16,5,'#b1c9d2',ink,3);
  rr(-86,206,52,15,5,'#9bbbc8',ink,3);

  // Two ions in each of five separated lanes; transport reverses smoothly.
  for(let lane=0;lane<lanes.length;lane++)for(let i=0;i<2;i++){
    const u=fract(charge*2+i/2+lane*0.137),x=-168+215*u,y=lanes[lane];
    ctx.save();ctx.globalAlpha=Math.pow(Math.sin(Math.PI*u),2)*0.90;
    const color=mix([168,219,220],[186,191,225],0.25+0.5*charge);
    circle(x,y,8,color,'#356579',2.2);
    line(x-3,y,x+3,y,'#36556b',1.7);line(x,y-3,x,y+3,'#36556b',1.7);
    ctx.restore();
  }

  // Lid, electrolyte vessel accents, and constant-polarity contacts.
  rr(-355,-257,590,37,12,'#abc4cd',ink,6);
  line(-330,-244,210,-244,'#d2e0e3',2.8);
  rr(-265,-294,50,37,9,'#89b6c7',ink,4);
  rr(95,-294,50,37,9,'#d1b07d',ink,4);
  line(-249,-276,-231,-276,'#28475e',3);
  line(111,-276,129,-276,'#5e4b42',3);line(120,-285,120,-267,'#5e4b42',3);
  line(-308,-191,-308,-175,'#b2d0d6',3);
  line(-308,193,-308,217,'#9cbec9',3);

  // Inline power/load instrument. Direction indicators crossfade at reversal.
  rr(-145,-400,170,72,14,'#789aaf',ink,5);
  for(let i=0;i<3;i++)rr(-126+i*25,-389,14,6,2,'#b4cdd8');
  ctx.save();ctx.globalAlpha=0.20+0.80*(0.5+0.5*direction);
  ctx.beginPath();ctx.moveTo(-88,-372);ctx.lineTo(-101,-364);ctx.lineTo(-88,-356);
  ctx.strokeStyle='#c6e2db';ctx.lineWidth=3;ctx.stroke();ctx.restore();
  ctx.save();ctx.globalAlpha=0.20+0.80*(0.5-0.5*direction);
  ctx.beginPath();ctx.moveTo(-32,-372);ctx.lineTo(-19,-364);ctx.lineTo(-32,-356);
  ctx.strokeStyle='#e1c594';ctx.lineWidth=3;ctx.stroke();ctx.restore();
  ctx.font='600 15px Arial, Helvetica, sans-serif';ctx.textAlign='center';ctx.textBaseline='middle';
  ctx.fillStyle='#e0ebeb';ctx.fillText('V',-60,-364);
  rr(-126,-344,132,6,2,'#3c617a');rr(-126,-344,12+charge*120,6,2,'#b5d9cf');

  // Voltage, current and transport indicators share the same charge timeline.
  rr(287,-171,139,373,20,'#28495e','#88aebd',5);
  rr(312,-151,89,10,4,'#7395aa');
  circle(357,-97,42,'#a7c2d1',ink,4.5);
  circle(357,-97,31,'#24445b','#6b90a7',2.5);
  for(let i=0;i<7;i++){
    const a=-2.6+i*2.3/6;
    line(357+Math.cos(a)*23,-97+Math.sin(a)*23,357+Math.cos(a)*27,-97+Math.sin(a)*27,'#c8dae0',1.9);
  }
  const a=-2.6+2.3*(0.22+0.78*charge);
  line(357,-97,357+Math.cos(a)*22,-97+Math.sin(a)*22,'#e2bf8e',2.8);
  circle(357,-97,4,'#d4e1e6',ink,1.5);
  ctx.fillStyle='#bad1dc';ctx.fillText('V',357,-73);
  const readouts=[charge,current,0.55+0.25*Math.cos(phase*2)];
  for(let i=0;i<3;i++){
    const y=-12+i*62;
    rr(309,y,96,10,4,'#1c364c');
    rr(309,y,10+86*readouts[i],10,4,i===0?'#d8b885':'#92cccf');
    for(let j=0;j<5;j++)line(312+j*22,y+21,312+j*22,y+25,'#5e859d',1.7);
  }
  for(let i=0;i<3;i++)circle(332+i*24,177,4.4,mix([65,106,127],[169,216,202],clamp(current-i*.12)),ink,1.5);

  // Rigid cell cradle and integrated voltage-history display.
  rr(-354,254,590,29,10,'#8eafbf',ink,5);
  rr(-309,349,83,28,9,'#345367',ink,4);
  rr(302,349,83,28,9,'#345367',ink,4);
  const base=ctx.createLinearGradient(0,274,0,359);
  base.addColorStop(0,'#9dbbc9');base.addColorStop(1,'#759ab2');
  rr(-374,274,815,85,26,base,ink,7);
  line(-346,289,412,289,'#d3e0e6',2.8);
  rr(-272,299,393,38,8,'#25465d','#62879f',3);
  ctx.save();rr(-254,305,357,25,3);ctx.clip();
  line(-254,326,103,326,'#4c6d84',1.4);ctx.beginPath();
  for(let i=0;i<=110;i++){
    const u=i/110,x=-254+u*357;
    const history=0.5-0.5*Math.cos(TAU*(loopT-(1-u)*12)/duration);
    const y=326-history*17;
    if(i===0)ctx.moveTo(x,y);else ctx.lineTo(x,y);
  }
  ctx.strokeStyle='#a7d9d1';ctx.lineWidth=2.3;ctx.stroke();ctx.restore();
  circle(-325,318,17,'#5c829f',ink,3.5);line(-325,307,-325,317,'#d6e5e8',2.4);
  ctx.beginPath();ctx.arc(-325,318,7.5,-0.75,Math.PI+0.75);ctx.strokeStyle='#d6e5e8';ctx.lineWidth=2.3;ctx.stroke();
  rr(153,303,242,28,8,'#52748f',ink,3);
  for(let i=0;i<8;i++)rr(169+i*27,311,12,12,3,mix([98,143,162],[180,215,212],0.5+0.5*Math.sin(phase*2-i*.4)));
  ctx.restore();
}

draw.duration=25;
draw.fps=60;
draw.exportSettings={width:3840,height:2160,bitrate:100000000,minimumBitrate:100000000};

/*
 * SCIENCE & RESEARCH 10 — SEISMIC RESEARCH SENSOR
 * Pure Canvas 2D; one continuous scene; seamless 25-second loop.
 * time is in SECONDS. Suggested export: 3840 x 2160 at 60 fps.
 * Export encoder requirement: at least 100,000,000 bits/second.
 * Canvas draws frames; the exporting encoder must enforce bitrate.
 * Prescribed periodic ground/mass response; analytical signal derivatives.
 * Only the spring changes pitch. Housing, inertial mass and rod stay rigid.
 * No assets, DOM, dependencies, 3D, blur, or background glow.
 */
function draw(ctx,time,width,height){
  const t=time;
  const duration=25;
  const sceneCount=1;
  const loopT=((t%duration)+duration)%duration;
  const sceneDuration=duration/sceneCount;
  const currentScene=Math.floor(loopT/sceneDuration);
  const sceneProgress=(loopT%sceneDuration)/sceneDuration;
  const minSide=Math.min(width,height);
  if(!(minSide>0)||!Number.isFinite(t))return;

  const TAU=Math.PI*2;
  const phase=TAU*(currentScene+sceneProgress);
  const unit=Math.min(minSide/1040,width/1210);
  const ink='#122b3d';
  const mix=(a,b,q)=>'rgb('+a.map((v,i)=>Math.round(v+(b[i]-v)*q)).join(',')+')';
  function responseAt(seconds){
    const s=((seconds%duration)+duration)%duration,p=TAU*s/duration,k=TAU/duration;
    const e=.65-.35*Math.cos(p),de=.35*k*Math.sin(p),dde=.35*k*k*Math.cos(p);
    function osc(base,coefficient,n,offset){
      const a=base+coefficient*e,w=n*k,u=n*p+offset,si=Math.sin(u),co=Math.cos(u);
      return [a*si,coefficient*de*si+a*w*co,(coefficient*dde-a*w*w)*si+2*coefficient*de*w*co];
    }
    const g1=osc(2.2,5,8,0),g2=osc(0,.8,16,.3),m1=osc(0,1.3,8,-.9),m2=osc(0,.35,16,-.4);
    const ground=g1[0]+g2[0],mass=m1[0]+m2[0];
    return {ground,mass,z:mass-ground,v:m1[1]+m2[1]-g1[1]-g2[1],a:m1[2]+m2[2]-g1[2]-g2[2],envelope:e};
  }
  const state=responseAt(loopT),relative=state.z;
  const massTop=-78+relative,massCenter=massTop+48,massBottom=massTop+96,pistonY=139+relative;
  function rr(x,y,w,h,r,fill,stroke,weight){
    r=Math.max(0,Math.min(r,w/2,h/2));
    ctx.beginPath();ctx.moveTo(x+r,y);ctx.lineTo(x+w-r,y);
    ctx.quadraticCurveTo(x+w,y,x+w,y+r);ctx.lineTo(x+w,y+h-r);
    ctx.quadraticCurveTo(x+w,y+h,x+w-r,y+h);ctx.lineTo(x+r,y+h);
    ctx.quadraticCurveTo(x,y+h,x,y+h-r);ctx.lineTo(x,y+r);
    ctx.quadraticCurveTo(x,y,x+r,y);ctx.closePath();
    if(fill){ctx.fillStyle=fill;ctx.fill();}
    if(stroke){ctx.strokeStyle=stroke;ctx.lineWidth=weight||4;ctx.stroke();}
  }
  function line(x1,y1,x2,y2,color,weight){
    ctx.beginPath();ctx.moveTo(x1,y1);ctx.lineTo(x2,y2);ctx.strokeStyle=color;ctx.lineWidth=weight;ctx.stroke();
  }
  function circle(x,y,r,fill,stroke,weight){
    ctx.beginPath();ctx.arc(x,y,r,0,TAU);
    if(fill){ctx.fillStyle=fill;ctx.fill();}
    if(stroke){ctx.strokeStyle=stroke;ctx.lineWidth=weight||3;ctx.stroke();}
  }
  ctx.save();ctx.setTransform(1,0,0,1,0,0);
  ctx.globalAlpha=1;ctx.globalCompositeOperation='source-over';
  ctx.shadowBlur=0;ctx.shadowOffsetX=0;ctx.shadowOffsetY=0;
  ctx.setLineDash([]);ctx.lineCap='round';ctx.lineJoin='round';
  const bg=ctx.createLinearGradient(0,0,width,height);
  bg.addColorStop(0,'#101f2e');bg.addColorStop(.53,'#203b4c');bg.addColorStop(1,'#293b50');
  ctx.fillStyle=bg;ctx.fillRect(0,0,width,height);
  ctx.translate(width/2-28*unit,height/2-11*unit);ctx.scale(unit,unit);
  // A small, prescribed vertical vibration is intentional for this sensor.
  ctx.translate(0,state.ground);
  ctx.beginPath();ctx.ellipse(38,383,428,11,0,0,TAU);ctx.fillStyle='rgba(4,14,25,.28)';ctx.fill();

  // The stratified foundation and its anchored sensor share the ground response.
  const foundation=ctx.createLinearGradient(0,260,0,363);
  foundation.addColorStop(0,'#8ca8b7');foundation.addColorStop(1,'#607f99');
  rr(-369,260,815,103,24,foundation,ink,7);
  ctx.save();rr(-359,273,795,80,15);ctx.clip();
  const layers=[{y:286,color:'#395b70'},{y:315,color:'#4a7287'},{y:343,color:'#607f95'}];
  for(let j=0;j<layers.length;j++){
    const layer=layers[j];ctx.beginPath();
    for(let i=0;i<=100;i++){
      const x=-365+i*810/100,y=layer.y+3*state.envelope*Math.sin(i/100*TAU*2.1-phase*6+j*.8);
      if(i===0)ctx.moveTo(x,y);else ctx.lineTo(x,y);
    }
    ctx.lineTo(445,366);ctx.lineTo(-365,366);ctx.closePath();ctx.fillStyle=layer.color;ctx.fill();
  }
  ctx.restore();
  rr(-308,238,48,31,8,'#7b9bb0',ink,4);
  rr(-16,238,48,31,8,'#7b9bb0',ink,4);

  // Rigid housing and fixed guide rails.
  const body=ctx.createLinearGradient(-349,-303,89,246);
  body.addColorStop(0,'#89a8b8');body.addColorStop(1,'#60869f');
  rr(-349,-303,438,549,29,body,ink,7);
  rr(-326,-273,392,493,19,'#1f4356','#b1c9d2',3.5);
  rr(-362,-322,464,36,12,'#aec5d1',ink,6);
  line(-337,-309,77,-309,'#d8e4e8',2.5);
  for(let i=0;i<4;i++)circle(-325+i*128,-304,3.5,'#658aa4',ink,1.3);
  rr(-143,-286,22,24,5,'#7799b0',ink,3.5);
  rr(-166,-263,68,18,6,'#b1c7d5',ink,4);
  for(const x of [-262,-2]){
    rr(x-6,-210,12,395,5,'#acc7d3',ink,3);
    line(x-1,-199,x-1,174,'#d7e5e6',2);
    rr(x-18,-219,36,14,4,'#7e9fb6',ink,3);
    rr(x-18,184,36,14,4,'#7e9fb6',ink,3);
  }

  // Fixed damper cylinder and its foundation mount.
  rr(-174,186,84,18,6,'#8faebf',ink,4);
  rr(-140,203,16,18,4,'#7797ad',ink,3);
  rr(-160,107,56,81,10,'#86a8bb',ink,4.5);
  rr(-154,115,44,65,5,'#345f72');
  ctx.fillStyle='#4d8898';ctx.fillRect(-152,117,40,61);
  rr(-138,103,12,10,3,'#25495d');

  // Nine fixed-count spring turns change pitch smoothly with relative motion.
  const springStart=-234,springEnd=massTop-13,turns=9;
  function springPath(){
    ctx.beginPath();ctx.moveTo(-132,-245);ctx.lineTo(-132,springStart);
    for(let i=1;i<turns*2;i++){
      const y=springStart+(springEnd-springStart)*i/(turns*2);
      ctx.lineTo(-132+(i%2?-16:16),y);
    }
    ctx.lineTo(-132,springEnd);ctx.lineTo(-132,massTop);
  }
  springPath();ctx.strokeStyle=ink;ctx.lineWidth=8;ctx.stroke();
  springPath();ctx.strokeStyle='#b9ced9';ctx.lineWidth=4.2;ctx.stroke();

  // The piston rod remains exactly 121 units long; its cap stays in the cylinder.
  rr(-136,massBottom,8,121,3,'#bfd5dd',ink,2.5);
  rr(-150,pistonY-4.5,36,9,3,'#9fd1cf',ink,2.3);
  line(-157,108,-140,108,'#c8d9df',2);
  line(-124,108,-107,108,'#c8d9df',2);

  // Guides, links and inertial mass translate together without scaling.
  for(const x of [-262,-2])rr(x-12,massCenter-14,24,28,6,'#839fb8',ink,3.5);
  line(-250,massCenter,-230,massCenter,ink,8);line(-250,massCenter,-230,massCenter,'#a9c2d2',3.5);
  line(-34,massCenter,-14,massCenter,ink,8);line(-34,massCenter,-14,massCenter,'#a9c2d2',3.5);
  const mass=ctx.createLinearGradient(-230,0,-34,0);
  mass.addColorStop(0,'#a3b9cf');mass.addColorStop(1,'#bed0de');
  rr(-230,massTop,196,96,14,mass,ink,6);
  rr(-216,massTop+15,168,66,9,'#6e92ad',ink,3);
  for(const x of [-215,-49])for(const y of [massTop+16,massTop+80])circle(x,y,3.8,'#d0e0e4',ink,1.5);
  rr(-201,massTop+27,9,42,3,'#adc9d5');rr(-72,massTop+27,9,42,3,'#adc9d5');
  ctx.font='700 23px Arial, Helvetica, sans-serif';ctx.textAlign='center';ctx.textBaseline='middle';
  ctx.fillStyle='#dce9eb';ctx.fillText('m',-132,massCenter+1);

  // Shared mounts keep the recorder attached to the vibrating instrument.
  rr(89,-166,59,22,6,'#7798b1',ink,4);
