/*
 * SCIENCE & RESEARCH 05 — OPTICAL SPECTROMETER
 * Pure Canvas 2D. One scene. Seamless 25-second loop.
 * time is in SECONDS. Suggested export: 3840 x 2160 at 60 fps.
 * Export encoder requirement: at least 100,000,000 bits/second.
 * Canvas draws frames; the encoder must enforce the video bitrate.
 * No DOM, external assets, dependencies, 3D, blur, or background glow.
 */
function draw(ctx, time, width, height) {
  const t = time;
  const duration = 25;
  const sceneCount = 1;
  const loopT = ((t % duration) + duration) % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;
  const minSide = Math.min(width, height);
  if (!(minSide > 0) || !Number.isFinite(t)) return;

  const TAU = Math.PI * 2;
  const phase = TAU * (currentScene + sceneProgress);
  const scan = 0.5 - 0.5 * Math.cos(phase);
  const unit = Math.min(minSide / 930, width / 1160);
  const ink = '#112a38';

  const clamp = v => Math.max(0, Math.min(1, v));
  const fract = v => v - Math.floor(v);
  const ease = v => {
    const q = clamp(v);
    return q * q * q * (q * (q * 6 - 15) + 10);
  };
  const mix = (a, b, q) =>
    'rgb(' + a.map((n, i) => Math.round(n + (b[i] - n) * clamp(q))).join(',') + ')';

  const spectrum = [
    [176, 159, 216],
    [126, 182, 222],
    [119, 210, 195],
    [228, 195, 133],
    [224, 155, 148]
  ];

  function spectralColor(q) {
    const p = clamp(q) * (spectrum.length - 1);
    const a = Math.min(spectrum.length - 2, Math.floor(p));
    return mix(spectrum[a], spectrum[a + 1], p - a);
  }

  function transmission(q) {
    return (
      0.88 -
      0.56 * Math.exp(-Math.pow((q - 0.48) / 0.15, 2)) -
      0.25 * Math.exp(-Math.pow((q - 0.78) / 0.09, 2))
    );
  }

  function rr(x, y, w, h, r, fill, stroke, weight) {
    r = Math.max(0, Math.min(r, w / 2, h / 2));
    ctx.beginPath();
    ctx.moveTo(x + r, y);
    ctx.lineTo(x + w - r, y);
    ctx.quadraticCurveTo(x + w, y, x + w, y + r);
    ctx.lineTo(x + w, y + h - r);
    ctx.quadraticCurveTo(x + w, y + h, x + w - r, y + h);
    ctx.lineTo(x + r, y + h);
    ctx.quadraticCurveTo(x, y + h, x, y + h - r);
    ctx.lineTo(x, y + r);
    ctx.quadraticCurveTo(x, y, x + r, y);
    ctx.closePath();
    if (fill) {
      ctx.fillStyle = fill;
      ctx.fill();
    }
    if (stroke) {
      ctx.strokeStyle = stroke;
      ctx.lineWidth = weight || 4;
      ctx.stroke();
    }
  }

  function line(x1, y1, x2, y2, color, weight) {
    ctx.beginPath();
    ctx.moveTo(x1, y1);
    ctx.lineTo(x2, y2);
    ctx.strokeStyle = color;
    ctx.lineWidth = weight;
    ctx.stroke();
