  const ease = v => { const q = clamp(v); return q * q * q * (q * (q * 6 - 15) + 10); };
  const ramp = (a, b, v) => ease((v - a) / (b - a));
  const blend = (a, b, v) => 'rgb(' + a.map((n, i) => Math.round(n + (b[i] - n) * v)).join(',') + ')';
  const sequence = ['A', 'G', 'T', 'C', 'G', 'A', 'C', 'T', 'A', 'C', 'G', 'T'];
