    if (fill) { ctx.fillStyle = fill; ctx.fill(); }
    if (stroke) { ctx.strokeStyle = stroke; ctx.lineWidth = lineWidth || 5; ctx.stroke(); }
  }
  function line(x1, y1, x2, y2, color, weight) {
    ctx.beginPath(); ctx.moveTo(x1, y1); ctx.lineTo(x2, y2);
    ctx.strokeStyle = color; ctx.lineWidth = weight; ctx.stroke();
  }
  function circle(x, y, r, fill, stroke, weight) {
    ctx.beginPath(); ctx.arc(x, y, r, 0, TAU);
    if (fill) { ctx.fillStyle = fill; ctx.fill(); }
    if (stroke) { ctx.strokeStyle = stroke; ctx.lineWidth = weight || 4; ctx.stroke(); }
  }
  function glassPath(inset) {
    if (!inset) {
      ctx.beginPath();
      ctx.moveTo(cx - 62, -315);
      ctx.lineTo(cx + 62, -315);
      ctx.lineTo(cx + 62, -197);
      ctx.lineTo(cx + 214, 127);
      ctx.quadraticCurveTo(cx + 237, 176, cx + 190, 181);
      ctx.lineTo(cx - 190, 181);
      ctx.quadraticCurveTo(cx - 237, 176, cx - 214, 127);
      ctx.lineTo(cx - 62, -197);
      ctx.closePath();
    } else {
      ctx.beginPath();
      ctx.moveTo(cx - 51, -307);
      ctx.lineTo(cx + 51, -307);
      ctx.lineTo(cx + 51, -194);
      ctx.lineTo(cx + 204, 133);
      ctx.quadraticCurveTo(cx + 220, 168, cx + 187, 170);
      ctx.lineTo(cx - 187, 170);
      ctx.quadraticCurveTo(cx - 220, 168, cx - 204, 133);
      ctx.lineTo(cx - 51, -194);
      ctx.closePath();
    }
  }
  function surface(x) {
    const u = (x - cx) / 218;
    return 27 - 14 * reaction
      + (6 + 5 * activity) * Math.sin(u * 3.6 + phase * 6)
      + 3.5 * Math.sin(u * 6.9 - phase * 4 + 0.6);
  }
  function liquidPath() {
    ctx.beginPath();
    for (let i = 0; i <= 64; i++) {
      const x = cx - 225 + 450 * i / 64;
      if (i === 0) ctx.moveTo(x, surface(x));
      else ctx.lineTo(x, surface(x));
    }
    ctx.lineTo(cx + 225, 190);
    ctx.lineTo(cx - 225, 190);
    ctx.closePath();
  }

  ctx.save();
  ctx.setTransform(1, 0, 0, 1, 0, 0);
  ctx.globalAlpha = 1;
  ctx.globalCompositeOperation = 'source-over';
  ctx.shadowBlur = 0;
  ctx.shadowOffsetX = 0;
  ctx.shadowOffsetY = 0;
  ctx.setLineDash([]);
  ctx.lineCap = 'round';
  ctx.lineJoin = 'round';

  // A broad, static color gradient; no background light spots or glow.
  const bg = ctx.createLinearGradient(0, 0, width, height);
  bg.addColorStop(0, '#0b1726');
  bg.addColorStop(0.52, '#122b39');
  bg.addColorStop(1, '#12363c');
  ctx.fillStyle = bg;
  ctx.fillRect(0, 0, width, height);
  ctx.translate(width / 2, height / 2 + 12 * unit);
  ctx.scale(unit, unit);

  // A solid contact shadow anchors the instrument without blur.
  ctx.beginPath(); ctx.ellipse(2, 378, 426, 12, 0, 0, TAU);
  ctx.fillStyle = 'rgba(3,13,22,0.30)'; ctx.fill();

  // Rigid stand and sensor bracket, behind the glass and clamp.
  rr(239, -366, 28, 618, 12, '#608596', ink, 6);
  line(249, -351, 249, 223, '#9ebac4', 4);
  rr(222, 215, 69, 42, 10, '#93b2bd', ink, 6);
  rr(265, -153, 56, 24, 7, '#668b9c', ink, 5);
  circle(281, -141, 5, '#cadce0');
  rr(cx + 60, -273, 307, 24, 7, '#6e9bab', ink, 5);
  circle(253, -261, 17, '#b0ccd3', ink, 5);
  line(246, -261, 260, -261, ink, 3);

  // Heating base: all motion is confined to indicators and controls.
  rr(-324, 340, 88, 28, 10, '#263d4b', ink, 5);
  rr(230, 340, 88, 28, 10, '#263d4b', ink, 5);
  const base = ctx.createLinearGradient(0, 245, 0, 352);
  base.addColorStop(0, '#759ba9');
  base.addColorStop(1, '#527888');
  rr(-392, 247, 784, 108, 29, base, ink, 7);
  rr(-398, 234, 796, 34, 15, '#a9c4cb', ink, 6);
  line(-365, 251, 365, 251, '#d0e1e3', 3);

  // Hot plate and restrained heat marks, physically under the flask.
  rr(-322, 207, 444, 30, 10, '#244552', ink, 5);
  rr(-302, 196, 404, 17, 7, '#a6c6cb', ink, 5);
  for (let i = 0; i < 10; i++) {
    rr(-279 + i * 37, 215, 22, 7, 3,
      mix([118, 130, 113], [246, 178, 98], heat), null, 0);
  }

  // Left thermostat control.
  circle(-303, 310, 32, '#23434f', ink, 5);
  for (let i = 0; i < 9; i++) {
    const a = -Math.PI * 1.15 + i * Math.PI * 1.3 / 8;
    line(-303 + Math.cos(a) * 23, 310 + Math.sin(a) * 23,
      -303 + Math.cos(a) * 27, 310 + Math.sin(a) * 27, '#bed2d5', 2.4);
  }
  circle(-303, 310, 17, '#f2bf80', ink, 3);
  const knobA = -2.8 + 2.5 * heat;
  line(-303, 310, -303 + Math.cos(knobA) * 12,
    310 + Math.sin(knobA) * 12, ink, 4);

  // Integrated process display, bounded by a generous inner margin.
  rr(-237, 280, 372, 52, 10, '#193542', '#91b1bc', 3);
  for (let i = 0; i < 6; i++) {
    const h = 9 + (13 + 9 * heat) * (0.5 + 0.5 * Math.sin(phase * 3 - i * 0.5));
    rr(-220 + i * 16, 317 - h, 8, h, 3, '#85d5ca');
  }
  line(-108, 290, -108, 322, '#466673', 2);
  ctx.save();
  rr(-94, 289, 213, 33, 3); ctx.clip();
  line(-94, 306, 119, 306, '#315662', 1.5);
  ctx.beginPath();
  for (let i = 0; i <= 70; i++) {
    const x = -94 + i * 213 / 70;
    const y = 306 + (4 + 6 * reaction) * Math.sin(i / 70 * TAU * 2 - phase * 5)
      + 1.5 * Math.sin(i / 70 * TAU * 4 - phase * 10);
    if (i === 0) ctx.moveTo(x, y); else ctx.lineTo(x, y);
  }
  ctx.strokeStyle = '#9ae6d2'; ctx.lineWidth = 2.6; ctx.stroke();
  ctx.restore();
  for (let i = 0; i < 3; i++) {
    const p = 0.5 + 0.5 * Math.cos(phase * 3 - i * TAU / 3);
    circle(173 + i * 32, 306, 6, mix([77, 110, 117], [174, 224, 188], p), ink, 2);
  }
  circle(330, 306, 22, '#2c4e5c', ink, 4);
  ctx.beginPath(); ctx.arc(330, 306, 10, -Math.PI * 0.28, Math.PI * 1.28);
  ctx.strokeStyle = '#c5dfdd'; ctx.lineWidth = 3; ctx.stroke();
  line(330, 292, 330, 304, '#c5dfdd', 3);

  // Faint vapor packets fade before a packet wraps to its starting point.
  for (let i = 0; i < 3; i++) {
    const u = fract(sceneProgress * 3 + i / 3);
    const alpha = Math.pow(Math.sin(Math.PI * u), 2) * (0.14 + 0.12 * reaction);
    ctx.save(); ctx.globalAlpha = alpha;
    const x = cx - 26 + i * 26;
    const y = -336 - u * 51;
    ctx.beginPath(); ctx.moveTo(x, y);
    ctx.bezierCurveTo(x - 8, y - 8, x + 8, y - 16, x + 2, y - 25);
    ctx.strokeStyle = '#bedbdc'; ctx.lineWidth = 3.2; ctx.stroke();
    ctx.restore();
  }

  // Erlenmeyer silhouette with one continuous contour.
  const glass = ctx.createLinearGradient(cx - 210, -100, cx + 210, 181);
  glass.addColorStop(0, 'rgba(158,206,209,0.13)');
  glass.addColorStop(1, 'rgba(100,162,180,0.08)');
  glassPath(false); ctx.fillStyle = glass; ctx.fill();

  ctx.save();
  glassPath(true); ctx.clip();
  const fluid = ctx.createLinearGradient(0, -12, 0, 181);
  fluid.addColorStop(0, mix([83, 218, 193], [78, 186, 218], reaction));
  fluid.addColorStop(1, mix([39, 158, 158], [40, 133, 182], reaction));
  liquidPath(); ctx.fillStyle = fluid; ctx.fill();

  ctx.save();
  liquidPath(); ctx.clip();
  // Low-contrast currents remain behind bubbles and measurement marks.
  for (let row = 0; row < 3; row++) {
    ctx.beginPath();
    for (let i = 0; i <= 36; i++) {
      const x = cx - 142 + i * 284 / 36;
      const y = 65 + row * 27 + 4.5 * Math.sin(i / 36 * TAU + phase * 4 + row);
      if (i === 0) ctx.moveTo(x, y); else ctx.lineTo(x, y);
    }
    ctx.strokeStyle = 'rgba(184,246,224,0.20)'; ctx.lineWidth = 2; ctx.stroke();
    const u = fract(sceneProgress * 4 + row / 3);
    const x = cx - 142 + u * 284;
    const y = 65 + row * 27 + 4.5 * Math.sin(u * TAU + phase * 4 + row);
    ctx.save(); ctx.globalAlpha = Math.pow(Math.sin(Math.PI * u), 2) * 0.43;
    circle(x, y, 3, '#c3f5de'); ctx.restore();
  }

  // The stirring bar has a fixed anchor and a small, controlled rocking arc.
  ctx.save(); ctx.translate(cx, 148); ctx.rotate(0.10 * Math.sin(phase * 5));
  rr(-42, -6, 84, 12, 6, '#d0e6d9', '#388c92', 2.5);
  line(-5, -3, 5, 3, '#83b9b2', 2); ctx.restore();

  for (let i = 0; i < 17; i++) {
    // Nine separated lanes; the two bubbles in a lane stay half a cycle apart.
    const lane = i % 9;
    const rank = Math.floor(i / 9);
    const cycles = 4 + lane % 3;
    const u = fract(sceneProgress * cycles + lane * 0.17320508075 + rank * 0.5);
    const x = cx - 116 + lane * 29 + 3 * Math.sin(phase * 3 + lane * 0.7);
    const target = surface(x) + 9;
    const rise = 0.78 * u + 0.22 * u * u;
    const y = 128 - (128 - target) * rise;
    const r = 2.7 + (i % 4) * 1.15;
    const alpha = Math.pow(Math.sin(Math.PI * u), 2) * (0.34 + 0.39 * activity);
    ctx.save(); ctx.globalAlpha = alpha;
    circle(x, y, r, 'rgba(211,255,229,0.16)', '#c4f6df', 1.7);
    ctx.restore();
  }
  ctx.restore();

  // Meniscus is clipped inside the glass instead of crossing its outline.
  ctx.beginPath();
  for (let i = 0; i <= 64; i++) {
    const x = cx - 225 + i * 450 / 64;
    if (i === 0) ctx.moveTo(x, surface(x)); else ctx.lineTo(x, surface(x));
  }
  ctx.strokeStyle = '#a4f0d7'; ctx.lineWidth = 3.4; ctx.stroke();
  ctx.restore();

  glassPath(false); ctx.strokeStyle = '#b5d5d9'; ctx.lineWidth = 6; ctx.stroke();
  // Short, flat glass accents do not imply a 3D surface or bloom.
  line(cx - 49, -220, cx - 49, -198, '#daf0eb', 3.2);
  line(cx - 78, -153, cx - 124, -57, 'rgba(202,233,230,0.58)', 4);
  line(cx - 181, 119, cx - 185, 130, 'rgba(202,233,230,0.55)', 4);

  for (let i = 0; i < 5; i++) {
    const y = -5 + i * 33;
    const right = cx + 62 + (y + 197) / 324 * 152 - 24;
    line(right - (i % 2 ? 17 : 27), y, right, y, 'rgba(209,239,231,0.78)', 2.8);
  }
  rr(cx - 75, -335, 150, 24, 8, '#7199a7', '#b5d5d9', 5);
  line(cx - 50, -325, cx + 50, -325, '#263f4c', 5);

  // Neck clamp masks only its intentional physical attachment to the glass.
  rr(cx - 80, -281, 160, 40, 9, '#548f9e', ink, 5);
  line(cx - 65, -271, cx + 65, -271, '#83bdc5', 3);
  circle(cx - 64, -261, 5, '#c9e2df', ink, 2);
  circle(cx + 64, -261, 5, '#c9e2df', ink, 2);

  // Temperature instrument stays clear of the stand and flask silhouette.
  rr(309, -178, 96, 300, 22, '#1b3948', '#7699a7', 5);
  ctx.fillStyle = '#c0d9dc'; ctx.font = '600 16px sans-serif';
  ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
  ctx.fillText('°C', 357, -150);
  rr(331, -119, 21, 211, 10, '#2a4d5b', '#96b7bd', 2.8);
  ctx.save(); rr(334, -116, 15, 207, 7); ctx.clip();
  const temperatureY = 39 - heat * 121;
  rr(334, temperatureY, 15, 100 - temperatureY, 6, '#f0ba77');
  ctx.restore();
  circle(341.5, 94, 19, '#f0ba77', '#96b7bd', 2.8);
  for (let i = 0; i < 9; i++) {
    const y = -108 + i * 22;
    line(365, y, i % 2 ? 375 : 383, y, '#91b4bd', 2.5);
  }
  circle(383, 96, 5, '#93d0bd');

  ctx.restore();
}

